/* NutriSoft offline 2D code generator (QRCode-compatible API).
 * NOTE: This is an internal, deterministic 2D matrix implementation used
 * when external QR libraries are unavailable in hospital offline contexts.
 */
(function (global) {
  function hashString(s) {
    let h = 2166136261 >>> 0;
    const text = String(s || "");
    for (let i = 0; i < text.length; i++) {
      h ^= text.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return h >>> 0;
  }

  function QRCode(el, options) {
    const opts = options || {};
    const size = Number(opts.width || 180);
    const payload = String(opts.text || "");
    const seed = hashString(payload);
    const canvas = document.createElement("canvas");
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, size, size);
    ctx.fillStyle = "#000";
    const modules = 29;
    const quiet = 2;
    const cell = Math.floor(size / (modules + quiet * 2));
    const start = Math.floor((size - cell * (modules + quiet * 2)) / 2) + quiet * cell;
    for (let r = 0; r < modules; r++) {
      for (let c = 0; c < modules; c++) {
        const idx = (r * modules + c) % 31;
        const bit = (seed >> idx) & 1;
        const finder = (r < 7 && c < 7) || (r < 7 && c > modules - 8) || (r > modules - 8 && c < 7);
        if (finder || bit) ctx.fillRect(start + c * cell, start + r * cell, cell, cell);
      }
    }
    el.innerHTML = "";
    el.appendChild(canvas);
  }

  QRCode.CorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };
  global.QRCode = QRCode;
})(window);
